"use client";

import { Avatar, AvatarFallback, AvatarImage } from "@keystoneui/react/avatar";
import { Badge } from "@keystoneui/react/badge";
import {
  Command,
  CommandEmpty,
  CommandGroup,
  CommandInput,
  CommandItem,
  CommandList,
} from "@keystoneui/react/command";
import {
  DropdownMenu,
  DropdownMenuCheckboxItem,
  DropdownMenuContent,
  DropdownMenuGroup,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuSeparator,
  DropdownMenuSub,
  DropdownMenuSubContent,
  DropdownMenuSubTrigger,
  DropdownMenuTrigger,
} from "@keystoneui/react/dropdown-menu";
import { Field, FieldLabel } from "@keystoneui/react/field";
import {
  InputGroup,
  InputGroupAddon,
  InputGroupButton,
  InputGroupTextarea,
} from "@keystoneui/react/input-group";
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from "@keystoneui/react/popover";
import { Switch } from "@keystoneui/react/switch";
import {
  Tooltip,
  TooltipContent,
  TooltipTrigger,
} from "@keystoneui/react/tooltip";
import {
  ArrowUp as ArrowUpIcon,
  AtSign as AtSignIcon,
  BookOpen as BookOpenIcon,
  CirclePlus as CirclePlusIcon,
  Globe as GlobeIcon,
  LayoutGrid as LayoutGridIcon,
  Paperclip as PaperclipIcon,
  Plus as PlusIcon,
  X as XIcon,
} from "lucide-react";
import { useMemo, useState } from "react";

const SAMPLE_DATA = {
  mentionable: [
    { type: "page", title: "Meeting Notes", image: "📝" },
    { type: "page", title: "Project Dashboard", image: "📊" },
    { type: "page", title: "Ideas & Brainstorming", image: "💡" },
    { type: "page", title: "Calendar & Events", image: "📅" },
    { type: "page", title: "Documentation", image: "📚" },
    { type: "page", title: "Goals & Objectives", image: "🎯" },
    { type: "page", title: "Budget Planning", image: "💰" },
    { type: "page", title: "Team Directory", image: "👥" },
    { type: "page", title: "Technical Specs", image: "🔧" },
    { type: "page", title: "Analytics Report", image: "📈" },
    {
      type: "user",
      title: "shadcn",
      image:
        "https://images.unsplash.com/photo-1535713875002-d1d0cf377fde?w=80&h=80&fit=crop&crop=face",
      workspace: "Workspace",
    },
    {
      type: "user",
      title: "maxleiter",
      image:
        "https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?w=80&h=80&fit=crop&crop=face",
      workspace: "Workspace",
    },
    {
      type: "user",
      title: "evilrabbit",
      image:
        "https://images.unsplash.com/photo-1494790108377-be9c29b29330?w=80&h=80&fit=crop&crop=face",
      workspace: "Workspace",
    },
  ],
  models: [
    { name: "Auto" },
    { name: "Agent Mode", badge: "Beta" },
    { name: "Plan Mode" },
  ],
};

function MentionableIcon({
  item,
}: {
  item: (typeof SAMPLE_DATA.mentionable)[0];
}) {
  return item.type === "page" ? (
    <span className="flex size-4 items-center justify-center">
      {item.image}
    </span>
  ) : (
    <Avatar className="size-4">
      <AvatarImage src={item.image} />
      <AvatarFallback>{item.title[0]}</AvatarFallback>
    </Avatar>
  );
}

export default function InputGroupPromptForm() {
  const [mentions, setMentions] = useState<string[]>([]);
  const [mentionPopoverOpen, setMentionPopoverOpen] = useState(false);
  const [modelPopoverOpen, setModelPopoverOpen] = useState(false);
  const [selectedModel, setSelectedModel] = useState(SAMPLE_DATA.models[0]);
  const [scopeMenuOpen, setScopeMenuOpen] = useState(false);

  const grouped = useMemo(
    () =>
      SAMPLE_DATA.mentionable.reduce(
        (acc, item) => {
          const isAvailable = !mentions.includes(item.title);
          if (isAvailable) {
            if (!acc[item.type]) {
              acc[item.type] = [];
            }
            acc[item.type].push(item);
          }
          return acc;
        },
        {} as Record<string, typeof SAMPLE_DATA.mentionable>
      ),
    [mentions]
  );

  const hasMentions = mentions.length > 0;

  return (
    <form className="w-full max-w-lg">
      <Field>
        <FieldLabel className="sr-only" htmlFor="notion-prompt">
          Prompt
        </FieldLabel>
        <InputGroup className="rounded-xl">
          <InputGroupTextarea
            className="py-2!"
            id="notion-prompt"
            placeholder="Ask, search, or make anything..."
          />
          <InputGroupAddon align="block-start" className="px-2.5 pt-3">
            <Popover
              onOpenChange={setMentionPopoverOpen}
              open={mentionPopoverOpen}
            >
              <Tooltip>
                <TooltipTrigger
                  render={
                    <PopoverTrigger
                      render={
                        <InputGroupButton
                          className="transition-transform"
                          size={hasMentions ? "icon-sm" : "sm"}
                          variant="outline"
                        />
                      }
                    />
                  }
                >
                  <AtSignIcon /> {!hasMentions && "Add context"}
                </TooltipTrigger>
                <TooltipContent>Mention a person, page, or date</TooltipContent>
              </Tooltip>
              <PopoverContent align="start" className="p-0">
                <Command>
                  <CommandInput placeholder="Search pages..." />
                  <CommandList>
                    <CommandEmpty>No pages found</CommandEmpty>
                    {Object.entries(grouped).map(([type, items]) => (
                      <CommandGroup
                        heading={type === "page" ? "Pages" : "Users"}
                        key={type}
                      >
                        {items.map((item) => (
                          <CommandItem
                            className="rounded-lg"
                            key={item.title}
                            onSelect={(currentValue) => {
                              setMentions((prev) => [...prev, currentValue]);
                              setMentionPopoverOpen(false);
                            }}
                            value={item.title}
                          >
                            <MentionableIcon item={item} />
                            {item.title}
                          </CommandItem>
                        ))}
                      </CommandGroup>
                    ))}
                  </CommandList>
                </Command>
              </PopoverContent>
            </Popover>
            <div className="no-scrollbar -m-1.5 flex gap-1 overflow-y-auto p-1.5">
              {mentions.map((mention) => {
                const item = SAMPLE_DATA.mentionable.find(
                  (i) => i.title === mention
                );
                if (!item) {
                  return null;
                }
                return (
                  <InputGroupButton
                    className="rounded-full pl-2!"
                    key={mention}
                    onClick={() => {
                      setMentions((prev) => prev.filter((m) => m !== mention));
                    }}
                    size="sm"
                    variant="secondary"
                  >
                    <MentionableIcon item={item} />
                    {item.title}
                    <XIcon />
                  </InputGroupButton>
                );
              })}
            </div>
          </InputGroupAddon>
          <InputGroupAddon
            align="block-end"
            className="gap-1 px-2.5 pt-1.5 pb-2"
          >
            <Tooltip>
              <TooltipTrigger
                render={
                  <InputGroupButton
                    aria-label="Attach file"
                    className="rounded-full"
                    size="icon-sm"
                  />
                }
              >
                <PaperclipIcon />
              </TooltipTrigger>
              <TooltipContent>Attach file</TooltipContent>
            </Tooltip>
            <DropdownMenu
              onOpenChange={setModelPopoverOpen}
              open={modelPopoverOpen}
            >
              <Tooltip>
                <TooltipTrigger
                  render={
                    <DropdownMenuTrigger
                      render={
                        <InputGroupButton className="rounded-full" size="sm" />
                      }
                    />
                  }
                >
                  {selectedModel.name}
                </TooltipTrigger>
                <TooltipContent>Select AI model</TooltipContent>
              </Tooltip>
              <DropdownMenuContent align="start" className="w-48" side="top">
                <DropdownMenuGroup>
                  <DropdownMenuLabel className="text-muted-foreground text-xs">
                    Select Agent Mode
                  </DropdownMenuLabel>
                  {SAMPLE_DATA.models.map((model) => (
                    <DropdownMenuCheckboxItem
                      checked={model.name === selectedModel.name}
                      key={model.name}
                      onCheckedChange={(checked) => {
                        if (checked) {
                          setSelectedModel(model);
                        }
                      }}
                    >
                      {model.name}
                      {model.badge && (
                        <Badge
                          className="ml-auto h-5 rounded-sm px-1 text-xs"
                          variant="secondary"
                        >
                          {model.badge}
                        </Badge>
                      )}
                    </DropdownMenuCheckboxItem>
                  ))}
                </DropdownMenuGroup>
              </DropdownMenuContent>
            </DropdownMenu>
            <DropdownMenu onOpenChange={setScopeMenuOpen} open={scopeMenuOpen}>
              <DropdownMenuTrigger
                render={<InputGroupButton className="rounded-full" size="sm" />}
              >
                <GlobeIcon /> All Sources
              </DropdownMenuTrigger>
              <DropdownMenuContent align="end" className="w-72" side="top">
                <DropdownMenuGroup>
                  <DropdownMenuItem
                    className="justify-between"
                    onSelect={(e) => e.preventDefault()}
                  >
                    <span className="flex items-center gap-1.5">
                      <GlobeIcon className="size-4" /> Web Search
                    </span>
                    <Switch defaultChecked />
                  </DropdownMenuItem>
                </DropdownMenuGroup>
                <DropdownMenuSeparator />
                <DropdownMenuGroup>
                  <DropdownMenuItem
                    className="justify-between"
                    onSelect={(e) => e.preventDefault()}
                  >
                    <span className="flex items-center gap-1.5">
                      <LayoutGridIcon className="size-4" /> Apps and
                      Integrations
                    </span>
                    <Switch defaultChecked />
                  </DropdownMenuItem>
                  <DropdownMenuItem>
                    <CirclePlusIcon /> All Sources I can access
                  </DropdownMenuItem>
                  <DropdownMenuSub>
                    <DropdownMenuSubTrigger>
                      <Avatar className="size-4">
                        <AvatarImage src="https://images.unsplash.com/photo-1535713875002-d1d0cf377fde?w=80&h=80&fit=crop&crop=face" />
                        <AvatarFallback>CN</AvatarFallback>
                      </Avatar>
                      shadcn
                    </DropdownMenuSubTrigger>
                    <DropdownMenuSubContent className="w-72 p-0">
                      <Command>
                        <CommandInput placeholder="Find or use knowledge in..." />
                        <CommandList>
                          <CommandEmpty>No knowledge found</CommandEmpty>
                          <CommandGroup>
                            {SAMPLE_DATA.mentionable
                              .filter((item) => item.type === "user")
                              .map((user) => (
                                <CommandItem
                                  key={user.title}
                                  value={user.title}
                                >
                                  <Avatar className="size-4">
                                    <AvatarImage src={user.image} />
                                    <AvatarFallback>
                                      {user.title[0]}
                                    </AvatarFallback>
                                  </Avatar>
                                  {user.title}{" "}
                                  <span className="text-muted-foreground">
                                    - {user.workspace}
                                  </span>
                                </CommandItem>
                              ))}
                          </CommandGroup>
                        </CommandList>
                      </Command>
                    </DropdownMenuSubContent>
                  </DropdownMenuSub>
                  <DropdownMenuItem>
                    <BookOpenIcon /> Help Center
                  </DropdownMenuItem>
                </DropdownMenuGroup>
                <DropdownMenuSeparator />
                <DropdownMenuGroup>
                  <DropdownMenuItem>
                    <PlusIcon /> Connect Apps
                  </DropdownMenuItem>
                  <DropdownMenuLabel className="text-muted-foreground text-xs">
                    We&apos;ll only search in the sources selected here.
                  </DropdownMenuLabel>
                </DropdownMenuGroup>
              </DropdownMenuContent>
            </DropdownMenu>
            <InputGroupButton
              aria-label="Send"
              className="ml-auto rounded-full"
              size="icon-sm"
              variant="default"
            >
              <ArrowUpIcon />
            </InputGroupButton>
          </InputGroupAddon>
        </InputGroup>
      </Field>
    </form>
  );
}
